import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, FlatList, Image, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { router } from "expo-router";
import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

type Category = { id:number; name:string; slug:string; image?:string|null; parent?:number|null; is_active?:boolean; children?:Category[] };
type TreeResponse = { categories: Category[] };

export default function VendorCategoriesScreen(){
 const [categories,setCategories]=useState<Category[]>([]);const [loading,setLoading]=useState(true);
 useEffect(()=>{djangoApi<TreeResponse>("/api/catalog/tree/").then(data=>setCategories(data.categories??[])).catch(error=>Alert.alert("تعذر التحميل",error instanceof Error?error.message:"لا يمكن جلب الفئات حاليًا.")).finally(()=>setLoading(false))},[]);
 const children=categories.flatMap(root=>(root.children??[]).map(child=>({...child,parent:root.id})));const all=[...categories,...children];
 return <ScreenContainer edges={["top","bottom","left","right"]} className="bg-[#F7F7F7]"><View style={styles.header}><TouchableOpacity onPress={()=>router.back()} style={styles.headerBtn}><MaterialIcons name="arrow-forward" size={24} color="#111"/></TouchableOpacity><Text style={styles.title}>فئات المتجر</Text><View style={{width:40}}/></View><View style={styles.info}><MaterialIcons name="info-outline" size={20} color="#168451"/><Text style={styles.infoText}>الفئات الأساسية تُدار من الإدارة. هنا تختارها عند إضافة المنتج، وتظهر دوائر الفئات تلقائيًا في واجهة المتجر للمنتجات المنشورة.</Text></View>{loading?<View style={styles.center}><ActivityIndicator color="#E60023"/></View>:<FlatList data={all} keyExtractor={item=>String(item.id)} contentContainerStyle={styles.list} ListEmptyComponent={<View style={styles.empty}><Text style={styles.emptyText}>لا توجد فئات منشورة حاليًا.</Text></View>} renderItem={({item})=><TouchableOpacity style={styles.card} onPress={()=>router.push(`/vendor/product/create?category=${item.id}` as never)}><View style={styles.image}>{item.image?<Image source={{uri:item.image}} style={styles.imageFill}/>:<MaterialIcons name="category" size={25} color="#777"/>}</View><View style={styles.copy}><Text style={styles.name}>{item.name}</Text><Text style={styles.slug}>{item.slug}</Text></View><MaterialIcons name="chevron-left" size={23} color="#999"/></TouchableOpacity>}/>}</ScreenContainer>
}
const styles=StyleSheet.create({header:{height:60,paddingHorizontal:16,flexDirection:"row-reverse",justifyContent:"space-between",alignItems:"center",backgroundColor:"#FFF",borderBottomWidth:1,borderColor:"#EEE"},headerBtn:{padding:8},title:{fontSize:18,fontWeight:"900",color:"#111"},info:{margin:12,padding:12,borderRadius:12,backgroundColor:"#F0F8F3",borderWidth:1,borderColor:"#DCEFE2",flexDirection:"row-reverse",alignItems:"flex-start",gap:8},infoText:{flex:1,color:"#4E5E54",fontSize:10,lineHeight:17,textAlign:"right"},list:{padding:12,paddingTop:0,paddingBottom:100,gap:9},card:{backgroundColor:"#FFF",borderRadius:12,padding:11,flexDirection:"row-reverse",alignItems:"center",gap:10,borderWidth:1,borderColor:"#EEE"},image:{width:48,height:48,borderRadius:11,backgroundColor:"#F4F4F4",alignItems:"center",justifyContent:"center",overflow:"hidden"},imageFill:{width:"100%",height:"100%"},copy:{flex:1,alignItems:"flex-end"},name:{fontSize:14,fontWeight:"900",color:"#222"},slug:{fontSize:9,color:"#999",marginTop:3},center:{flex:1,alignItems:"center",justifyContent:"center"},empty:{padding:45,alignItems:"center"},emptyText:{color:"#888",fontSize:13}}
);